--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` int(11) NOT NULL,
  `staff_number` varchar(50) DEFAULT NULL COMMENT 'Unique staff identification number',
  `names` varchar(255) DEFAULT NULL,
  `college` varchar(100) DEFAULT NULL,
  `campus` varchar(100) DEFAULT NULL,
  `school` varchar(100) DEFAULT NULL COMMENT 'School/Unit',
  `staff_type` varchar(100) DEFAULT NULL COMMENT 'Academic or Administrative',
  `department` varchar(100) DEFAULT NULL,
  `accademic_rank` varchar(100) DEFAULT NULL,
  `role` varchar(100) DEFAULT NULL COMMENT 'administrative position',
  `title` varchar(50) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL COMMENT 'personal Email',
  `ur_email` varchar(255) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `gender` varchar(100) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `resetcode` varchar(20) DEFAULT NULL COMMENT 'Password reset verification code',
  `image` varchar(255) DEFAULT 'uploads/profile/icon1.png',
  `active` tinyint(1) DEFAULT 1 COMMENT '1=Active, 0=Inactive',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

